{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/topic-chips.json
    A centered row of topic pills (static links). tone inverse: on a dark band with an icon per topic; default: outlined.
    Props (p): topics, tone. -#}
{%- set v_topics = ui_def(p['topics'], none) -%}
{%- set v_tone = ui_def(p['tone'], 'default') -%}
{%- set c_3 -%}
  {%- for v_topic in ui_l(v_topics) %}
    {%- if ui_t(ui_eq(v_tone, 'inverse')) %}
      {%- set c_1 -%}
        {%- if ui_t(ui_get(v_topic, ['icon'])) %}
          {{ ui_include('ui/lucide-icon/lucide-icon.html.j2', {'p': {'Name': ui_s(ui_get(v_topic, ['icon'])), 'Size': 16}}) }}
        {%- endif %}
        {{ ui_text(ui_get(v_topic, ['name'])) }}
      {%- endset -%}
      {{ ui_include('ui/button/button.html.j2', {'p': {'Href': '#/', 'Variant': 'ghost', 'Size': 'sm', 'Class': 'gap-2 text-background inset-ring-background/30 hover:bg-background/10', 'Attrs': ui_attrs(['data-testid', 'hero-topic'])}, 'children': c_1}) }}
    {%- else %}
      {%- set c_2 -%}
        {{ ui_text(ui_get(v_topic, ['name'])) }}
      {%- endset -%}
      {{ ui_include('ui/button/button.html.j2', {'p': {'Href': '#/', 'Variant': 'outline', 'Size': 'sm', 'Attrs': ui_attrs(['data-testid', 'hero-topic'])}, 'children': c_2}) }}
    {%- endif %}
  {%- endfor %}
{%- endset -%}
{{ ui_include('ui/group/group.html.j2', {'p': {'Gap': '2', 'Align': 'center', 'Justify': 'center', 'Class': 'flex-wrap', 'Attrs': ui_attrs(['data-testid', 'hero-topics'])}, 'children': c_3}) }}
